require __DIR__.'/../config/app.php';$me=require_role('admin');
$id=(int)($_GET['id']??$_POST['id']??0);$role=in_array(($_GET['role']??$_POST['role']??'student'),['student','committee','admin'],true)?($_GET['role']??$_POST['role']):'student';$error='';
$q=db()->prepare('SELECT id,name,email,role FROM users WHERE id=? AND role=?');$q->execute([$id,$role]);$account=$q->fetch();if(!$account){http_response_code(404);exit('Account not found.');}if($role==='admin'&&$id!==(int)$me['id']){http_response_code(403);exit('You cannot change another administrator account.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
 if($name===''||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/@marwadiuniversity\.ac\.in$/i',$email)||($password!==''&&strlen($password)<8))$error='Enter a valid name, university email, and optional password of at least 8 characters.';
 else{try{if($password!=='')$q=db()->prepare('UPDATE users SET name=?,email=?,password_hash=? WHERE id=? AND role=?')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$id,$role]);else db()->prepare('UPDATE users SET name=?,email=? WHERE id=? AND role=?')->execute([$name,$email,$id,$role]);flash(ucfirst($role).' account updated.');go($role==='admin'?'admin/admin-accounts.php':'admin/users.php?role='.$role);}catch(Throwable $t){$error='Could not save. Check whether this email is already in use.';}$account['name']=$name;$account['email']=$email;}
}
$pageTitle='Edit Account';$bodyClass='dashboard-page admin-page';$activePage='users';$adminSection='users';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">ACCOUNT DIRECTORY</span><h1>Edit <?=ucfirst($role)?> Account</h1><p>Update account details or set a new temporary password.</p></div></header><?php require __DIR__.'/section-nav.php';?><?php if($error):?><div class="inline-error"><?=e($error)?></div><?php endif;?><section class="admin-work-card"><form method="post" class="form-card admin-event-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="role" value="<?=$role?>"><label>Name<input required maxlength="120" name="name" value="<?=e($account['name'])?>"></label><label>University email<input type="email" required name="email" pattern=".+@marwadiuniversity\.ac\.in" value="<?=e($account['email'])?>"></label><label>New password <small>Leave blank to keep current password.</small><input type="password" name="password" minlength="8" autocomplete="new-password"></label><div class="admin-form-actions"><a class="btn outline" href="<?=url('admin/users.php?role='.$role)?>">Cancel</a><button class="btn primary" type="submit">Save Account</button></div></form></section></main></div><?php require __DIR__.'/../includes/footer.php';
